SELECT fk.name AS fk_name,SCHEMA_NAME(a.schema_id) AS child_schema,a.name AS child_table,ca.name AS child_column,SCHEMA_NAME(b.schema_id) AS parent_schema,b.name AS parent_table,cb.name AS parent_column,fc.constraint_column_id,fk.is_disabled,fk.is_not_trusted,fk.delete_referential_action_desc,fk.update_referential_action_desc FROM sys.foreign_keys fk JOIN sys.foreign_key_columns fc ON fc.constraint_object_id=fk.object_id JOIN sys.tables a ON a.object_id=fk.parent_object_id JOIN sys.tables b ON b.object_id=fk.referenced_object_id JOIN sys.columns ca ON ca.object_id=a.object_id AND ca.column_id=fc.parent_column_id JOIN sys.columns cb ON cb.object_id=b.object_id AND cb.column_id=fc.referenced_column_id WHERE a.name LIKE 'ProductosServicios%' OR b.name LIKE 'ProductosServicios%' ORDER BY fk.name,fc.constraint_column_id